declare_lint ! { # [doc = " The `missing_copy_implementations` lint detects potentially-forgotten"] # [doc = " implementations of [`Copy`] for public types."] # [doc = ""] # [doc = " [`Copy`]: https://doc.rust-lang.org/std/marker/trait.Copy.html"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(missing_copy_implementations)]"] # [doc = " pub struct Foo {"] # [doc = "     pub field: i32"] # [doc = " }"] # [doc = " # fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Historically (before 1.0), types were automatically marked as `Copy`"] # [doc = " if possible. This was changed so that it required an explicit opt-in"] # [doc = " by implementing the `Copy` trait. As part of this change, a lint was"] # [doc = " added to alert if a copyable type was not marked `Copy`."] # [doc = ""] # [doc = " This lint is \"allow\" by default because this code isn't bad; it is"] # [doc = " common to write newtypes like this specifically so that a `Copy` type"] # [doc = " is no longer `Copy`. `Copy` types can result in unintended copies of"] # [doc = " large data which can impact performance."] pub MISSING_COPY_IMPLEMENTATIONS , Allow , "detects potentially-forgotten implementations of `Copy`" }